'use strict';
const coverageView={project:'',collection:'',status:'',q:'',offset:0,rows:[]};
const coverageStates={expanded:'Configured paths expanded',partial:'Partial expansion','not-loaded':'Ready to expand',unconfigured:'No nested adapter',unmatched:'No matching metadata roots','configuration-error':'Configuration needs review'};
async function openCoverage(project){close();if(project!==undefined&&project!==coverageView.project){coverageView.project=project;coverageView.collection='';}state.project=coverageView.project||'all';state.mode='coverage';state.category='';state.q='';$('search').value='';window.scrollTo(0,0);drawNavigation();await loadCoverage();}
function drawCoverageNavigation(){drawWorkNavigation();document.querySelector('.toolbar').hidden=true;$('work-controls').hidden=true;$('assets').className='storage-layout';$('heading').textContent='Metadata coverage';$('subheading').textContent='Configured paths across registered works. Direct assets remain available without a nested adapter.';$('category-heading').textContent='Registered works';$('more').hidden=true;}
async function loadCoverage(more=false){const gen=++state.generation;if(!more){coverageView.basis=null;coverageView.offset=0;coverageView.rows=[];$('assets').replaceChildren(node('p','empty','Reading captured metadata coverage…'));}notice('');try{const d=await api('/api/storage/coverage',{project:coverageView.project,collection:coverageView.collection,state:coverageView.status,q:coverageView.q,offset:coverageView.offset});if(gen!==state.generation||state.mode!=='coverage')return;if(Object.entries(d.snapshots).some(([id,sha])=>state.projects.find(p=>p.id===id)?.commit!==sha))throw Error('Snapshot changed. Refresh the catalog.');if(more&&coverageView.basis!==d.basis)throw Error('Coverage changed. Use Refresh coverage before loading more.');coverageView.basis=d.basis;coverageView.rows.push(...d.items);drawCoverage(d);}catch(e){if(gen===state.generation)notice(e.message);}}
function drawCoverage(d){const area=$('assets');area.replaceChildren();const stats=document.querySelector('.stats');stats.replaceChildren();const counts=d.states_before_status_filter;for(const [v,label] of [[Object.values(counts).reduce((a,b)=>a+b,0),'works before status filter'],[counts.expanded||0,'configured paths expanded'],[counts['not-loaded']||0,'ready to expand'],[(counts.partial||0)+(counts['configuration-error']||0),'partial / review']]){const s=node('div');s.append(node('span','',fmt.format(v)),node('small','',label));stats.append(s);}
 const controls=node('div','object-filters');const change=(k,v)=>{coverageView[k]=v;if(k==='project'){coverageView.collection='';state.project=v||'all';drawNavigation();}loadCoverage();};controls.append(diskSelect('Coverage project',coverageView.project,[['','All projects'],...state.projects.map(p=>[p.id,p.label])],v=>change('project',v)));const families=state.projects.find(p=>p.id===coverageView.project)?.collections.filter(c=>c.top_level!==false)||[];const family=diskSelect('Coverage family',coverageView.collection,[['','All families'],...families.map(c=>[c.id,c.label])],v=>change('collection',v));family.disabled=!coverageView.project;controls.append(family,diskSelect('Coverage status',coverageView.status,[['','All states'],...Object.entries(coverageStates)],v=>change('status',v)));const q=node('input');q.type='search';q.setAttribute('aria-label','Search coverage');q.placeholder='Find a registered work';q.value=coverageView.q;q.onchange=()=>change('q',q.value);controls.append(q);const refresh=node('button','button secondary','Refresh coverage');refresh.onclick=()=>loadCoverage();controls.append(refresh);area.append(controls,node('p','callout','This is nested-metadata coverage, not complete production dependencies, active jobs or retained custody. No package or media bytes are read by this report.'));
 const table=node('table','object-manager-table');const head=node('tr');['Project / work','Family','Metadata state','Roots / gaps','Review'].forEach(t=>head.append(node('th','',t)));table.append(head);for(const row of coverageView.rows){const w=row.work,tr=node('tr');const title=node('td');const b=node('button','object-title',w.title);b.onclick=()=>inspectWork(w);title.append(node('small','muted',projectLabel(w.project)),b);const status=node('td','',coverageStates[row.state]);const roots=node('td','',row.roots==null?'Not configured':row.roots+' admitted roots');if(row.failures)roots.append(node('small','muted',row.failures+' failed roots'));if(row.error)roots.append(node('small','muted',row.error));const actions=node('td');const open=node('button','button secondary','Manage objects');open.onclick=()=>openObjectManager(w.project,w);actions.append(open);tr.append(title,node('td','',w.category),status,roots,actions);table.append(tr);}const wrap=node('div','object-table-wrap');wrap.append(table);area.append(wrap);if(!coverageView.rows.length)area.append(node('p','empty','No works match these filters.'));if(coverageView.rows.length<d.total){const more=node('button','button secondary','More works');more.onclick=()=>{coverageView.offset=coverageView.rows.length;loadCoverage(true);};area.append(more);}$('result-count').textContent=d.total+' matching works';document.querySelector('main footer').textContent='States describe admitted paths in exact Git snapshots. No matching adapter is not a proof that dependencies are absent.';
}
function versionComparisonControls(d,area){if(d.versions.length<2)return;const controls=node('div','object-filters');const options=d.versions.map(v=>[v.label,v.label+(v.current?' · current':'')]);const from=diskSelect('Compare from version',(d.versions.find(v=>!v.current)||d.versions[0]).label,options,()=>{}),to=diskSelect('Compare to version',(d.versions.find(v=>v.current)||d.versions.at(-1)).label,options,()=>{});const result=node('section','version-comparison');const compare=node('button','button secondary','Compare declared bytes');compare.onclick=async()=>{const selected=state.selected;compare.disabled=true;result.replaceChildren(node('p','muted','Reading admitted version metadata…'));try{const r=await api('/api/storage/compare',{project:d.work.project,snapshot:d.commit,collection:d.work.collection,work:d.work.id,from:from.querySelector('select').value,to:to.querySelector('select').value});if(state.selected!==selected)return;if(Object.entries(r.snapshots).some(([id,sha])=>state.projects.find(p=>p.id===id)?.commit!==sha))throw Error('Snapshot changed. Refresh the catalog.');result.replaceChildren(node('p','callout',r.configured_paths_complete?'Both versions expanded under configured metadata paths. Complete dependency and retention coverage remain unknown.':'Partial or direct-only comparison. Set membership reflects loaded declarations; unexpanded content remains unknown.'),node('p','muted',r.removed_with_other_records+' removed-set objects have known declarations outside this record. Other retained versions of this record and unregistered consumers are not covered.'));for(const key of ['added','shared','removed']){const g=r[key],s=section(key[0].toUpperCase()+key.slice(1)+' declarations · '+g.count+' objects · '+bytes(g.bytes));for(const item of g.items){const e=node('div','stream');e.append(node('strong','',bytes(item.object.bytes)),node('small','mono',item.object.sha256));if(key==='removed')e.append(node('p','',item.known_other_records+' known other records · not a complete reference count'));for(const owner of item.other_records||[])e.append(node('small','mono',projectLabel(owner[0])+' · '+owner[1]));e.append(node('small','muted',item.observed_copies.length+' observed cache copies; unobserved locations remain unknown'));for(const copy of item.observed_copies.slice(0,8))e.append(node('small','mono',copy.root+' · '+bytes(copy.bytes)));s.append(e);}if(g.count>g.items.length)s.append(node('p','muted','Showing the largest '+g.items.length+' of '+g.count+' objects.'));result.append(s);}result.append(node('p','callout','Removed from this version does not authorize deletion. Verified reclaim is unknown. No bytes were moved or removed.'));}catch(e){result.replaceChildren(node('p','callout',e.message));}finally{compare.disabled=false;}};controls.append(from,to,compare);area.append(controls,result);}
